// V118b-L11 (parallel): Hope Street COMMUTE SHOP keeper only (the three V118 passers-by were removed).
// V118c: the keeper's head is a whole-head UV unwrap (hopest118-head.js + keeper/head.png, generated by
// tools/hopest118c_head.py from 5 registered photos): face / sides / back / crown / under-chin islands and modelled
// ears with their own islands. The cast's built-in head is skipped (opts.noHead) and this mesh rides bones.head.
// Built with the existing Level 11 PS1 cast generator (retro-cast-v75.js: one continuous torso with joined sleeves,
// 19 bones, 128x128 nearest-filtered face/face-blink/body/hair textures, blink by face swap, 24 Hz stepped pose),
// so he matches the indoor Level 11 residents. Arms are re-posed to rest on the counter. The skinned rig stays
// invisible and a plain mesh is CPU-skinned from it (SwiftShader drops the context on GPU-skinned meshes here).
import * as T from './vendor/three.module.min.js';
import {createRetroActor75} from './retro-cast-v75.js?v=118c';
import {HEAD118C} from './hopest118-head.js?v=118c';
const A=new URL('./assets/l11-v118/keeper/',import.meta.url).href;
function tex(n){const t=new T.TextureLoader().load(A+n+'.png?v=118c');t.colorSpace=T.SRGBColorSpace;t.minFilter=t.magFilter=T.NearestFilter;t.generateMipmaps=false;return t;}
// un-mirrored Hope frame: kiosk x 61.7..66.1, street face z 2.78; he stands behind the counter facing the street (-z)
export const HOPE118_KEEPER={x:63.9,z:3.5,y:.15,face:[0,-1]};
const _v=new T.Vector3(),_w=new T.Vector3(),_e=new T.Euler();
export function createHope118People({toWorld,Y,angle}){
 const group=new T.Group();group.name='Hope St V118b keeper';
 if(globalThis.H118_SKIP?.includes('keeper'))return{object:group,people:[],update(){}};
 const textures={face:tex('head'),faceBlink:tex('head-blink'),body:tex('body')};
 const actor=createRetroActor75(T,'wallman',textures,{seed:11802,castShadow:true,noHead:true,skinUV:HEAD118C.skinUV,hairUV:HEAD118C.skinUV});
 const rig=actor.mesh;rig.visible=false;
 const src=rig.geometry,shown=new T.BufferGeometry();
 for(const k of['uv','color'])if(src.attributes[k])shown.setAttribute(k,src.attributes[k]);
 shown.setAttribute('position',src.attributes.position.clone());shown.setAttribute('normal',src.attributes.normal.clone());
 for(const g of src.groups)shown.addGroup(g.start,g.count,g.materialIndex);
 const mesh=new T.Mesh(shown,rig.material);mesh.name='Hope St V118b / keeper (CPU-skinned V75 cast)';mesh.castShadow=mesh.receiveShadow=true;mesh.frustumCulled=false;
 actor.group.add(mesh);group.add(actor.group);
 // unwrapped head on the head bone (bind: head bone at y 1.535, chin row at 1.552); the cast's face material swaps head/head-blink
 const hg=new T.BufferGeometry();hg.setAttribute('position',new T.BufferAttribute(HEAD118C.position,3));hg.setAttribute('normal',new T.BufferAttribute(HEAD118C.normal,3));hg.setAttribute('uv',new T.BufferAttribute(HEAD118C.uv,2));
 const headMat=rig.material[1];headMat.vertexColors=false;headMat.needsUpdate=true;
 const head=new T.Mesh(hg,headMat);head.name='Hope St V118c / keeper unwrapped head';head.position.y=HEAD118C.chinY-1.535;head.castShadow=head.receiveShadow=true;head.frustumCulled=false;
 actor.bones.head.add(head);
 const K=HOPE118_KEEPER,p=toWorld(K.x,K.z);actor.group.position.set(p.x,Y+K.y,p.z);actor.group.rotation.y=angle+Math.atan2(-K.face[0],K.face[1]);
 const B=actor.bones,pose=(name,x,y,z)=>{_e.set(x,y,z);B[name].quaternion.setFromEuler(_e);};
 let lastTick=-1,last=0;
 function step(cam){
  const now=performance.now()/1000;if(now-last<1/30)return;last=now;
  actor.update(now,0);
  const tick=Math.floor(now*24);if(tick===lastTick)return;lastTick=tick;
  // counter lean: both forearms resting on the counter top, weight shifting, occasional glance down the street
  const sway=Math.sin(now*.41)*.5+Math.sin(now*.17)*.5,look=Math.sin(now*.23)*Math.sin(now*.11);
  B.spine.rotation.x=.10;B.chest.rotation.x=.12+.01*Math.sin(now*1.7);B.chest.rotation.z=-.02*sway;B.hips.rotation.z=.025*sway;
  B.head.rotation.set(.05,look*.55,0);B.neck.rotation.y=look*.2;
  pose('upperArmL',-.6,0,.17);pose('foreArmL',-1.12,.25,0);pose('handL',.25,0,-.2);
  pose('upperArmR',-.62,0,-.15);pose('foreArmR',-1.1,-.3,0);pose('handR',.25,0,.2);
  actor.group.updateMatrixWorld(true);
  if(cam&&cam.getWorldPosition(_w).distanceTo(actor.group.getWorldPosition(_v))>60&&mesh.userData.skinned)return;
  mesh.userData.skinned=true;rig.skeleton.update();
  const sp=src.attributes.position,dp=shown.attributes.position;
  for(let i=0;i<sp.count;i++){_v.fromBufferAttribute(sp,i);rig.applyBoneTransform(i,_v);dp.setXYZ(i,_v.x,_v.y,_v.z);}
  dp.needsUpdate=true;shown.computeVertexNormals();
 }
 if(!globalThis.H118_NOANIM)mesh.onBeforeRender=(r,s,cam)=>step(cam);
 step(null);
 return{object:group,people:[actor],update:()=>{}};
}
